package com.ledgerx.application.ledger;
import java.time.LocalDate;
public final class RecordPatch {private final String id,categoryId,accountId,note;private final RecordType type;private final LocalDate occurredOn,settlementOn;private final long amountMinor;public RecordPatch(String i,RecordType t,long a,LocalDate o,String c,String ac,LocalDate s,String n){id=i;type=t;amountMinor=a;occurredOn=o;categoryId=c;accountId=ac;settlementOn=s;note=n;}public String getId(){return id;}public RecordType getType(){return type;}public long getAmountMinor(){return amountMinor;}public LocalDate getOccurredOn(){return occurredOn;}public String getCategoryId(){return categoryId;}public String getAccountId(){return accountId;}public LocalDate getSettlementOn(){return settlementOn;}public String getNote(){return note;}}
